def versiegeln(apps, schema_editor):
    """Vorhandene Einträge je Organisation in der Reihenfolge ihrer Anlage verketten."""
    from audit.chain import GENESIS, changes_digest, entry_digest

    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute("SELECT set_config('app.bypass_rls', 'on', true)")
    AuditEntry = apps.get_model("audit", "AuditEntry")
    # order_by() ohne Felder: Die Standardsortierung (Zeit, id) käme sonst mit in das
    # DISTINCT, und jede Einheit käme einmal je Eintrag dran (Dogado 31.10.2026).
    org_ids = sorted(
        set(AuditEntry.objects.order_by().values_list("organization_id", flat=True).distinct())
    )
    for org_id in org_ids:
        prev, seq, batch = GENESIS, 0, []
        for entry in AuditEntry.objects.filter(organization_id=org_id).order_by("id").iterator():
            seq += 1
            entry.seq = seq
            entry.prev_hash = prev
            entry.changes_hash = changes_digest(entry)
            entry.hash = entry_digest(entry, seq, prev, entry.changes_hash)
            prev = entry.hash
            batch.append(entry)
            if len(batch) >= 1000:
                AuditEntry.objects.bulk_update(batch, ["seq", "prev_hash", "hash", "changes_hash"])
                batch = []
        if batch:
            AuditEntry.objects.bulk_update(batch, ["seq", "prev_hash", "hash", "changes_hash"])


